import type { Id, IsoDate } from "./common";

export type CustomRequestStatus =
  | "DRAFT"
  | "GENERATING"
  | "PUBLISHED"
  | "WITH_OFFERS"
  | "ACCEPTED"
  | "IN_PRODUCTION"
  | "DELIVERED"
  | "CANCELLED"
  | "EXPIRED";

export type DesignStatus = "PENDING" | "PROCESSING" | "COMPLETED" | "FAILED";

/** Image generated by AI from the request description. */
export interface CustomDesign {
  id: Id;
  provider: string;
  model: string | null;
  prompt: string;
  status: DesignStatus;
  imageUrl: string | null;
  isSelected: boolean;
  createdAt: IsoDate;
}

export type OfferType = "ACCEPT_PRICE" | "COUNTER_OFFER";
export type OfferStatus = "SENT" | "ACCEPTED" | "REJECTED" | "WITHDRAWN" | "EXPIRED";

export interface CustomOffer {
  id: Id;
  requestId: Id;
  masterId: Id;
  masterName: string;
  storeSlug: string;
  type: OfferType;
  price: number;
  currency: string;
  estimatedDays: number;
  message: string | null;
  designId: Id | null;
  status: OfferStatus;
  createdAt: IsoDate;
}

export interface CustomRequest {
  id: Id;
  buyerId: Id;
  buyerName: string;
  targetMasterId: Id | null;
  title: string;
  description: string;
  shapeId: Id | null;
  styleId: Id | null;
  colorIds: Id[];
  motifIds: Id[];
  sizeNotes: string | null;
  offeredPrice: number | null;
  currency: string;
  desiredDate: string | null;
  status: CustomRequestStatus;
  acceptedOfferId: Id | null;
  designs: CustomDesign[];
  offers: CustomOffer[];
  expiresAt: IsoDate | null;
  createdAt: IsoDate;
}

export type CustomRequestInput = Pick<
  CustomRequest,
  "title" | "description" | "shapeId" | "styleId" | "colorIds" | "motifIds" | "sizeNotes" | "offeredPrice" | "desiredDate" | "targetMasterId"
>;

export interface OfferInput {
  type: OfferType;
  price: number;
  estimatedDays: number;
  message: string;
  designId: Id | null;
}
